In SIAR, every MLS Group is governed by an epoch-based key schedule: Epoch Secret ($E_k$) : Derived at every group state transition (member added, member removed, or periodic self-update). Application Secret ($A_k$) : Used with HKDF-Expand-Label to derive the sender encryption keys and ChaCha20-Poly1305 nonces for chat packets. Confirmation Tag : Verifies that all members have converged to the exact same cryptographic tree state. pub struct MlsGroupState { pub group_id: [u8; 32], pub epoch: u64, pub tree_kem: TreeKemState, pub interim_transcript_hash: [u8; 32], pub confirmed_transcript_hash: [u8; 32], pub roster: HashMap<LeafIndex, PublicIdentity>,
} impl MlsGroupState { /// Execute a self-update commit to achieve Post-Compromise Security (PCS) pub fn self_update(&mut self, my_leaf: LeafIndex) -> Result<(MlsCommit, [u8; 32]), MlsError> { let (new_leaf_secret, new_leaf_keypair) = generate_fresh_kem_key(); let path_secrets = self.tree_kem.update_path(my_leaf, new_leaf_keypair)?; let commit = MlsCommit::new(self.epoch + 1, my_leaf, path_secrets); self.advance_epoch(&commit)?; Ok((commit, self.tree_kem.root_secret())) }
}

