const DTN_METADATA_TABLE: TableDefinition<&[u8; 32], &[u8]> = TableDefinition::new("dtn_meta"); pub struct DtnStorageEngine { db: Database, max_storage_bytes: u64, current_usage_bytes: u64,
} impl DtnStorageEngine { /// Persist a bundle atomically with zero-copy memory mapping pub fn store_bundle(&mut self, bundle_id: &[u8; 32], raw_bytes: &[u8], meta: &BundleMetadata) -> Result<(), StorageError> { // Enforce quota: evict lower-priority expired bundles if required if self.current_usage_bytes + (raw_bytes.len() as u64) > self.max_storage_bytes { self.evict_lowest_priority(raw_bytes.len() as u64)?; } let write_txn = self.db.begin_write()?; { let mut bundles = write_txn.open_table(DTN_BUNDLES_TABLE)?; let mut metadata = write_txn.open_table(DTN_METADATA_TABLE)?; bundles.insert(bundle_id, raw_bytes)?; metadata.insert(bundle_id, &postcard::to_allocvec(meta)?)?; } write_txn.commit()?; self.current_usage_bytes += raw_bytes.len() as u64; Ok(()) }
}

